/** 19.6: release signing from env (CI secrets) or keystore.properties; without them the debug key signs (installable test build). */
fun signingValue(key: String, env: String): String? {
    val e = System.getenv(env)
    if (!e.isNullOrBlank()) return e
    val f = rootProject.file("keystore.properties")
    if (!f.isFile) return null
    val p = Properties()
    f.inputStream().use { p.load(it) }
    return p.getProperty(key)?.takeIf { it.isNotBlank() }
}

/**
 * 19.6.1: SHA-256 of the release certificate, pinned into the APK as a string resource. CigramIntegrity compares it with
 * the certificate the APK is really signed with, so a re-signed (cracked / repackaged) copy refuses to run.
 * Empty when there is no release keystore (debug-key test build) or it cannot be read: the check is then skipped.
 */
fun releaseSignerSha256(): String {
    val store = signingValue("storeFile", "CIGRAM_STORE_FILE") ?: return ""
    val f = file(store)
    if (!f.isFile) return ""
    val password = signingValue("storePassword", "CIGRAM_STORE_PASSWORD")?.toCharArray() ?: return ""
    val alias = signingValue("keyAlias", "CIGRAM_KEY_ALIAS") ?: return ""
    for (type in listOf("JKS", "PKCS12")) {
        try {
            val ks = KeyStore.getInstance(type)
            f.inputStream().use { ks.load(it, password) }
            val cert = ks.getCertificate(alias) ?: continue
            return MessageDigest.getInstance("SHA-256").digest(cert.encoded)
                .joinToString("") { "%02X".format(it) }
        } catch (e: Exception) {
            // try the next keystore type
        }
    }
    return ""
}

